import {domains,algorithmConcepts} from './domain-course.js';
import {concepts} from './course.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountDomains(onSelect,onOpen){
 const root=document.getElementById('domainCards');
 root.innerHTML=domains.map((d,i)=>`<article class="domain-card" style="--domain:${d.color}"><button class="domain-open" data-domain="${i}" aria-label="探索${d.name}方向"><span class="domain-index">0${i+1} / ${d.en}</span><h3>${d.name}<span>↗</span></h3><p>${d.question}</p><small>${d.tasks}</small></button><div class="algorithm-chips">${d.ids.map(id=>`<button data-algorithm="${id}">${algorithmConcepts.find(c=>c.id===id).title}<span>→</span></button>`).join('')}</div><p class="domain-path">${d.path}</p></article>`).join('');
 root.addEventListener('click',e=>{const alg=e.target.closest('[data-algorithm]'),domain=e.target.closest('[data-domain]');if(alg)onOpen(Number(alg.dataset.algorithm));else if(domain)onSelect(Number(domain.dataset.domain))});
 document.getElementById('allAlgorithms').onclick=()=>onSelect(-1);
}
export function renderCourse(active,onOpen){
 const root=document.getElementById('coursePanel');root.hidden=!active.course;if(!active.course){root.innerHTML='';return}
 const c=active.course;
 root.innerHTML=`<div class="course-heading"><div><span class="eyebrow">FROM INTUITION TO A TRAINING PIPELINE</span><h3>把机制，连成一门算法课</h3></div><span class="course-badge">经典算法专题</span></div><div class="prerequisite-row"><span>建议先理解</span>${c.prerequisites.map(id=>`<button data-prerequisite="${id}">${concepts.find(x=>x.id===id).title} ↗</button>`).join('')}</div><div class="course-tabs" role="tablist" aria-label="算法课程内容"><button role="tab" id="tab-training" aria-controls="courseTabContent" data-course-tab="training">训练流程</button><button role="tab" id="tab-code" aria-controls="courseTabContent" data-course-tab="code">代码实践</button><button role="tab" id="tab-paper" aria-controls="courseTabContent" data-course-tab="paper">论文导读</button></div><div id="courseTabContent" class="course-tab-content" role="tabpanel"></div>`;
 const content=root.querySelector('#courseTabContent');let request=0,codeText='';
 async function select(tab){
  const current=++request;root.querySelectorAll('[data-course-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.courseTab===tab);b.setAttribute('aria-selected',String(b.dataset.courseTab===tab))});content.setAttribute('aria-labelledby','tab-'+tab);
  if(tab==='training'){content.innerHTML=`<div class="io-grid"><div><span>输入与数据</span><p>${escape(c.input)}</p></div><div><span>输出与任务</span><p>${escape(c.output)}</p></div></div><div class="objective"><span>优化什么</span><p>${escape(c.objective)}</p></div><ol class="training-pipeline">${c.training.map((s,i)=>`<li><b>0${i+1}</b><span>${escape(s)}</span></li>`).join('')}</ol><div class="evaluation-note"><b>怎样判断效果</b><p>${escape(c.evaluation)}</p></div><div class="course-boundary"><b>本课的范围</b><p>${escape(c.boundary)}</p></div>`;return}
  if(tab==='paper'){content.innerHTML=`<a class="paper-link" href="${active.source}" target="_blank" rel="noopener"><span>原论文 / 作者资料</span><strong>${escape(c.paper)}</strong><i>阅读原始来源 ↗</i></a>${(c.references??[]).map(r=>`<p><a href="${r.url}" target="_blank" rel="noopener">${escape(r.title)} ↗</a></p>`).join('')}<h4>带着三个问题读</h4><ol class="paper-questions">${c.reading.map(s=>`<li>${escape(s)}</li>`).join('')}</ol><p class="course-fineprint">先对照本课的信息流与目标，再读论文中的结构、公式和实验设置。本页是阅读指引；教学代码的简化范围已单独列出。</p>`;return}
  content.innerHTML=`<div class="code-intro"><p>可直接下载的独立 Python 教学代码。多数使用合成数据，DQN/PPO 使用 CartPole；不下载大型数据集或预训练权重。</p><div class="code-actions"><a href="${c.code}" download="${c.file}.py">下载 ${c.file}.py ↓</a><a href="./neuro-atlas-course-code.zip" download>全部 14 份代码 ZIP ↓</a><a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noopener">安装 PyTorch ↗</a><button id="copyCourseCode">复制代码</button></div></div><div class="code-setup"><span>准备与运行</span><code>Python 3.11 + PyTorch${[35,36].includes(active.id)?' + gymnasium + stable-baselines3':''}\npython ${c.file}.py --steps ${[35,36].includes(active.id)?'2048':'20'} --device auto</code><p>${[35,36].includes(active.id)?'--steps 表示请求的环境交互步数，PPO 会按完整 rollout 取整。':'--steps 表示参数更新次数。'}auto 在 CUDA 可用时使用 GPU；可显式选择 cpu 或 cuda。</p></div><pre class="course-code"><code id="courseCodeText">正在载入代码…</code></pre><div class="course-boundary"><b>代码做到哪一步</b><p>${escape(c.boundary)}</p></div><p class="course-fineprint">代码已做短程执行检查。成功运行与有限损失不能证明论文效果；完整训练仍需数据划分、预算、多种子和独立评估。</p>`;
  const target=content.querySelector('#courseCodeText');
  try{const response=await fetch(c.code);if(!response.ok)throw Error('load');const text=await response.text();if(current!==request)return;codeText=text;target.textContent=text}catch{if(current===request)target.textContent='代码预览暂时不可用，可用上方下载链接获取。'}
 }
 root.onclick=async e=>{const tab=e.target.closest('[data-course-tab]'),pre=e.target.closest('[data-prerequisite]');if(tab)select(tab.dataset.courseTab);if(pre)onOpen(Number(pre.dataset.prerequisite));if(e.target.id==='copyCourseCode'){try{if(!codeText)return;await navigator.clipboard.writeText(codeText);e.target.textContent='已复制 ✓'}catch{e.target.textContent='可在代码框中选择并复制'}}};
 select('training');
}
